{"explanation":"A Riemann sum estimates the area under y = x² by splitting [0, 2] into n strips of width Δx = 2/n and adding up the areas of the rectangles, Σ f(xᵢ)·Δx. With left endpoints the rectangles sit under the rising curve, so the sum comes out too small. With right endpoints it comes out too big, and midpoints land very close. As n grows, all three approach the exact area, ∫₀² x² dx = 8/3 ≈ 2.6667. Use the slider to change n and the buttons to pick the sampling rule.","manimCode":"const ax = new Axes({ xRange: [0, 2.2, 0.5], yRange: [0, 4.5, 1], xLength: 7, yLength: 5.5, tips: false });
ax.moveTo([-2, -0.2, 0]);
const curve = ax.plot(x => x * x, { color: YELLOW, xRange: [0, 2.1] });
scene.add(ax, curve);

const fLabel = new MathTex({ latex: 'y = x^2', color: YELLOW });
await fLabel.waitForRender();
fLabel.moveTo(ax.c2p(1.45, 4.2));
scene.add(fLabel);

const title = new MathTex({ latex: '\\int_0^2 x^2\\,dx = \\tfrac{8}{3} \\approx 2.6667' });
await title.waitForRender();
title.scale(0.75);
title.moveTo([3.9, 1.6, 0]);
scene.add(title);

let n = 4;
let mode = 'left';
let rects = new VGroup();
let sumLabel = null;
let modeLabel = null;

function sampleX(i, dx) {
  if (mode === 'left') return i * dx;
  if (mode === 'right') return (i + 1) * dx;
  return (i + 0.5) * dx;
}

function rebuild() {
  scene.remove(rects);
  rects = new VGroup();
  const dx = 2 / n;
  let total = 0;
  for (let i = 0; i < n; i++) {
    const x0 = i * dx, x1 = (i + 1) * dx;
    const h = Math.pow(sampleX(i, dx), 2);
    total += h * dx;
    const p = new Polygon({
      vertices: [ax.c2p(x0, 0), ax.c2p(x1, 0), ax.c2p(x1, h), ax.c2p(x0, h)],
      color: BLUE_B
    });
    p.setFill(BLUE_D, 0.55);
    p.setStrokeWidth(n > 40 ? 0.5 : 1.5);
    rects.add(p);
  }
  scene.add(rects);
  scene.remove(curve);
  scene.add(curve);

  if (sumLabel) scene.remove(sumLabel);
  sumLabel = new Text({ text: 'n = ' + n + '\nSum ≈ ' + total.toFixed(4) + '\nError = ' + (total - 8 / 3).toFixed(4), color: WHITE, fontSize: 26 });
  sumLabel.moveTo([3.9, 0, 0]);
  scene.add(sumLabel);

  if (modeLabel) scene.remove(modeLabel);
  const names = { left: 'Left endpoints', right: 'Right endpoints', mid: 'Midpoints' };
  modeLabel = new Text({ text: names[mode], color: BLUE_B, fontSize: 26 });
  modeLabel.moveTo([3.9, -1.5, 0]);
  scene.add(modeLabel);
}

rebuild();

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'Rectangles (n)', min: 1, max: 100, value: 4, step: 1, onChange: (v) => { n = Math.round(v); rebuild(); } });
controls.addButton({ label: 'Left', onClick: () => { mode = 'left'; rebuild(); } });
controls.addButton({ label: 'Midpoint', onClick: () => { mode = 'mid'; rebuild(); } });
controls.addButton({ label: 'Right', onClick: () => { mode = 'right'; rebuild(); } });

await scene.wait(999999);"}

